with Ada.Text_IO; use Ada.Text_IO;

procedure Main is
   procedure Greet (Name : String; Times : Integer) is
   begin
      for I in 1 .. Times loop
         Put_Line ("Hi, " & Name);
      end loop;
   end Greet;
begin
   Greet ("Ada", 2);
   Greet ("Bob", 1);
end Main;

with Ada.Text_IO; use Ada.Text_IO;

procedure Main is
   function Square (X : Integer) return Integer is
   begin
      return X * X;
   end Square;

   function Max (A, B : Integer) return Integer is
   begin
      if A > B then
         return A;
      else
         return B;
      end if;
   end Max;
begin
   Put_Line (Integer'Image (Square (4)));
   Put_Line (Integer'Image (Max (3, 9) + 1));
end Main;

with Ada.Text_IO; use Ada.Text_IO;

procedure Main is
   Score : Integer := 5;
   H, R  : Integer;

   procedure Add_Bonus (Points : in out Integer) is
   begin
      Points := Points + 10;
   end Add_Bonus;

   procedure Split (Total : in Integer; Half : out Integer; Rest : out Integer) is
   begin
      Half := Total / 2;
      Rest := Total mod 2;
   end Split;
begin
   Add_Bonus (Score);
   Put_Line ("Score:" & Integer'Image (Score));
   Split (7, H, R);
   Put_Line (Integer'Image (H) & Integer'Image (R));
end Main;

