procedure Main is
   type Item is record
      Name  : String (1 .. 5);
      Price : Natural;
   end record;
   type Cart is array (1 .. 3) of Item;
   C     : Cart := (("Apple", 3), ("Bread", 2), ("Juice", 4));
   Total : Natural := 0;
